/// The icon weight token (ADR-0013 decision 4). `number` is the value a numeric weight token carries,
/// so `DSTokenSet.Icon.weight` resolves to a case through `init(number:)` (critic C-23).
public enum DSIconWeight: String, CaseIterable, Hashable, Sendable {
    case thin
    case light
    case regular
    case medium
    case bold
    case heavy

    public var number: Int {
        switch self {
        case .thin: 200
        case .light: 300
        case .regular: 400
        case .medium: 500
        case .bold: 700
        case .heavy: 800
        }
    }

    /// The San Francisco weight an SF Symbol renders at.
    public var fontWeight: Font.Weight {
        switch self {
        case .thin: .thin
        case .light: .light
        case .regular: .regular
        case .medium: .medium
        case .bold: .bold
        case .heavy: .heavy
        }
    }

    /// The Phosphor cut an image set renders (the four drawn cuts; Phosphor has no medium).
    public var phosphorCut: String {
        switch self {
        case .thin: "thin"
        case .light: "light"
        case .regular: "regular"
        case .medium: "bold"
        case .bold: "bold"
        case .heavy: "bold"
        }
    }

    /// The weight this one steps to under Bold Text on iOS, iPadOS and watchOS (ADR-0021 §3);
    /// macOS and the web have no such setting. The web saturates at the bold cut, which Phosphor's four cuts impose.
    public var boldText: DSIconWeight {
        switch self {
        case .thin: .light
        case .light: .regular
        case .regular: .medium
        case .medium: .bold
        case .bold: .heavy
        case .heavy: .heavy
        }
    }

    /// The weight a numeric token such as `DSTokenSet.Icon.weight` names, or nil when no weight carries it.
    public init?(number: Int) {
        switch number {
        case 200: self = .thin
        case 300: self = .light
        case 400: self = .regular
        case 500: self = .medium
        case 700: self = .bold
        case 800: self = .heavy
        default: return nil
        }
    }
}

/// The icon style token (ADR-0013 decision 4): the SF variant or rendering mode, and the Phosphor cut.
public enum DSIconStyle: String, CaseIterable, Hashable, Sendable {
    case outline
    case filled
    case duotone

    /// The `.symbolVariant` an SF Symbol takes, or nil when the style keeps the plain variant.
    public var symbolVariant: SymbolVariants? {
        switch self {
        case .outline: nil
        case .filled: .fill
        case .duotone: nil
        }
    }

    /// The `.symbolRenderingMode` the style asks for, or nil for the inherited mode.
    public var renderingMode: SymbolRenderingMode? {
        switch self {
        case .outline: nil
        case .filled: nil
        case .duotone: .hierarchical
        }
    }

    /// The Phosphor cut an image set renders, or nil when the style renders the weight cut.
    public var phosphorCut: String? {
        switch self {
        case .outline: nil
        case .filled: "fill"
        case .duotone: "duotone"
        }
    }
}

